    Bug 1826285 - Try to fix intermittent comm/mail/components/unifiedtoolbar/test/browser/browser_customizableItems.js | Default items order stable for extensions. r=freaktechnik


    Theory: The add-ons are sorted by date. In the test the add-ons are registered after one another, so may up having same date,
    which will mess up the expected ordering when sorting.

    Differential Revision: https://phabricator.services.mozilla.com/D270128

diff --git a/mail/components/unifiedtoolbar/modules/CustomizableItems.sys.mjs b/mail/components/unifiedtoolbar/modules/CustomizableItems.sys.mjs
index eb9ccee46fd..9907f1e9d81 100644
--- a/mail/components/unifiedtoolbar/modules/CustomizableItems.sys.mjs
+++ b/mail/components/unifiedtoolbar/modules/CustomizableItems.sys.mjs
@@ -41,13 +41,18 @@ export async function registerExtension(id, spaces = ["mail"]) {
     return;
   }
   const addon = await lazy.AddonManager.getAddonByID(id);
+  if (!addon) {
+    console.warn(`Add-on ${id} not found.`);
+  }
   EXTENSIONS.push({
     id,
     spaces,
     installDate: addon?.installDate ?? new Date(),
   });
   EXTENSIONS.sort(
-    (extA, extB) => extA.installDate.valueOf() - extB.installDate.valueOf()
+    (extA, extB) =>
+      extA.installDate.valueOf() - extB.installDate.valueOf() ||
+      extA.id.localeCompare(extB.id)
   );
 }
